from common import Q, SR, notice
from c2 import ORD

def R(p, o, x, **k):                 # single question, right answer first
    return Q(o, 0, x, p=p, **k)

def M(word, o, x):                   # meaning of a feeling or attitude word (choices in English)
    return Q(o, 0, x, d=f"'{word}'의 뜻으로 알맞은 것을 고르십시오.", dl="Choose the meaning.", lo=True)

def IN(text, box, pos, x):           # given sentence goes in ㉠..㉣ (pos 0..3)
    return Q(["㉠", "㉡", "㉢", "㉣"], pos, x, p=text + f"<br><br><b>[보기] {box}</b>")

def SET(text, qs):                   # qs = [(question, [right, ...], x)]
    return SR([(q, o, 0, x) for q, o, x in qs], text)

